body.script:
document.addEventListener('DOMContentLoaded', function() {
    var toggle = document.getElementById('tm-sidebar-toggle');
    var sidebar = document.getElementById('tm-sidebar');
    if (toggle && sidebar) {
        toggle.addEventListener('click', function() {
            sidebar.classList.toggle('open');
        });
    }
});

t.script:
function loadStudents(courseId) {
    var sel = document.getElementById('report_student_id');
    sel.innerHTML = 'Loading...';
    if (!courseId) { sel.innerHTML = '— Select Course First —'; return; }
    fetch('/my/tutor/progress-reports/students?course_id=' + courseId)
        .then(r => r.json())
        .then data => {
            sel.innerHTML = '— Select Student —';
            data.forEach(s => { sel.innerHTML += '' + s.name + ''; });
        });
}
// Auto-load if course preselected
var cs = document.getElementById('report_course_id');
if (cs && cs.value) loadStudents(cs.value);
